# Falls back gracefully on systems where "Segoe UI" isn't installed
# (e.g. Linux/macOS) instead of tkinter silently substituting a
# mismatched default font for every widget.
def _resolve_font_family():
    preferred = ["Segoe UI", "Segoe UI Variable", "Helvetica Neue", "Arial"]
    try:
        import tkinter.font as tkfont
        available = set(tkfont.families())
        for name in preferred:
            if name in available:
                return name
    except Exception:
        pass
    return preferred[-1]


