# Emoji glyphs render as flat, colorless line-icons unless a real
# color-emoji font backs them — most UI fonts (including Segoe UI)
# don't include emoji glyphs at all, so we resolve a dedicated font
# for icon-only labels instead of reusing the body font for them.
def _resolve_emoji_font():
    preferred = ["Segoe UI Emoji", "Noto Color Emoji", "Apple Color Emoji", "Segoe UI Symbol"]
    try:
        import tkinter.font as tkfont
        available = set(tkfont.families())
        for name in preferred:
            if name in available:
                return name
    except Exception:
        pass
    return FONT  # graceful fallback: still readable, just monochrome


