    def _settings_file(self):
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), "skybook_settings.json")

    def _load_app_settings(self):
        try:
            with open(self._settings_file(), "r", encoding="utf-8") as handle:
                data = json.load(handle)
            self.language = str(data.get("language", "English"))
            self.notifications_enabled = bool(data.get("notifications", True))
        except (OSError, ValueError, TypeError):
            self.language = "English"
            self.notifications_enabled = True

    def _save_app_settings(self):
        with open(self._settings_file(), "w", encoding="utf-8") as handle:
            json.dump({
                "language": self.language,
                "notifications": self.notifications_enabled,
            }, handle, ensure_ascii=False, indent=2)

