    def clear(self):
        """Destroy all top-level child widgets so each page re-renders cleanly."""
        for child in self.winfo_children():
            child.destroy()

    def background(self, wallpaper_type="default"):
        """Render a full-screen wallpaper with page-specific image selection.

        wallpaper_type="auth" is used by Login / Register / Admin Login and
        looks for login-specific wallpaper files first. Other pages keep the
        existing generic wallpaper behaviour.
        """
        bg = ctk.CTkFrame(
            self,
            fg_color=NAVY,
            corner_radius=0,
        )
        bg.place(x=0, y=0, relwidth=1, relheight=1)
        bg.lower()

        project_dir = os.path.dirname(os.path.abspath(__file__))
        root_candidates = [
            project_dir,
            os.getcwd(),
            os.path.join(project_dir, "assets"),
            os.path.join(project_dir, "images"),
        ]
        if wallpaper_type == "auth":
            # Dedicated wallpaper for Login / Register / Admin Login.
            # Keep the old generic names as fallbacks so the app still opens
            # if the dedicated file has not been copied into the project yet.
            candidates = [
                "login_wallpaper.jpg", "login_wallpaper.png",
                "login_background.jpg", "login_background.png",
                "airplane.jpg", "airplane.png",
                "wallpaper.jpg", "wallpaper.png",
                "background.jpg", "background.png",
            ]
        else:
            candidates = [
                "home_wallpaper.jpg", "home_wallpaper.png",
                "home_background.jpg", "home_background.png",
                "airplane.jpg", "airplane.png", "wallpaper.jpg", "wallpaper.png",
                "background.jpg", "background.png",
            ]

        image_path = None
        seen = set()
        for base_dir in root_candidates:
            for file_name in candidates:
                path = os.path.abspath(os.path.join(base_dir, file_name))
                if path in seen:
                    continue
                seen.add(path)
                if os.path.exists(path):
                    image_path = path
                    break
            if image_path:
                break

        if not image_path:
            return bg

        try:
            source_image = Image.open(image_path).convert("RGBA")
        except Exception:
            return bg

        label = ctk.CTkLabel(
            self, image=None, text="", fg_color="transparent"
        )
        label.place(x=0, y=0, relwidth=1, relheight=1)
        # Keep the wallpaper above the fallback background, but below all page widgets.
        # Do NOT lower the image below `bg` because `bg` is an opaque frame.
        label.lift(bg)

        self._background_source_image = source_image
        self._background_label = label
        self._background_resize_job = None

        def resize_background(event=None):
            if not label.winfo_exists():
                return
            if self._background_resize_job is not None:
                try:
                    self.after_cancel(self._background_resize_job)
                except Exception:
                    pass
            self._background_resize_job = self.after(60, apply_background_size)

        def apply_background_size():
            self._background_resize_job = None
            if not label.winfo_exists():
                return
            # The app runs fullscreen, so use the actual desktop resolution
            # instead of the current widget size.  CTkLabel keeps a PIL/Tk
            # image at its native size; using screen dimensions here prevents
            # the image from stopping early and leaving a black strip on the
            # right/bottom side.
            w = max(2, int(self.winfo_screenwidth()))
            h = max(2, int(self.winfo_screenheight()))
            try:
                resized = ImageOps.fit(
                    self._background_source_image,
                    (w, h),
                    method=Image.Resampling.LANCZOS,
                    centering=(0.5, 0.48),
                )
                tk_image = ctk.CTkImage(
                    light_image=resized, dark_image=resized, size=(w, h)
                )
                label.place_configure(x=0, y=0, width=w, height=h,
                                      relwidth=0, relheight=0)
                label.configure(image=tk_image)
                label.image = tk_image
                self._background_image = tk_image
            except Exception:
                pass

        self.bind("<Configure>", resize_background, add="+")
        self.after_idle(apply_background_size)
        return bg

