    def build_date_field(self, parent, x, y, mindate, width=250, height=34, maxdate=None):
        """Project-styled date field with a white input box and themed
        calendar button.  The returned container is packed by the caller,
        so it never mixes ``place`` and ``pack`` geometry managers."""
        container = ctk.CTkFrame(
            parent, width=width, height=height, corner_radius=5,
            fg_color="#081F33", border_width=2, border_color=PRIMARY_COLOR
        )
        container.pack_propagate(False)

        entry = ctk.CTkEntry(
            container, width=max(80, width - 42), height=height - 8,
            corner_radius=3, fg_color="#081F33", border_width=0,
            text_color=TEXT_PRIMARY, placeholder_text_color="#60798F",
            font=FONT_LABEL, justify="left"
        )
        entry.place(x=7, y=4)
        entry.insert(0, mindate.strftime("%d-%m-%Y"))

        ctk.CTkButton(
            container, text="▾", width=30, height=height - 8,
            corner_radius=3, fg_color="#081F33", hover_color="#EEF7FF",
            text_color=PRIMARY_COLOR, font=FONT_LABEL_BOLD,
            command=lambda: self.open_calendar_popup(entry, mindate, maxdate)
        ).place(x=width - 34, y=4)
        return container, entry

    def open_calendar_popup(self, entry_widget, mindate, maxdate=None):
        """Themed calendar popup used by build_date_field's dropdown button."""
        popup = ctk.CTkToplevel(self)
        popup.title("Select Date")
        popup.geometry("300x340")
        popup.resizable(False, False)
        popup.configure(fg_color=NAVY)
        popup.transient(self)
        popup.grab_set()

        try:
            current = datetime.strptime(entry_widget.get().strip(), "%d-%m-%Y")
        except ValueError:
            current = mindate

        cal = Calendar(
            popup, selectmode="day", date_pattern="dd-mm-yyyy",
            mindate=mindate, maxdate=maxdate,
            year=current.year, month=current.month, day=current.day,
            background="#081F33", foreground=TEXT_PRIMARY,
            headersbackground=NAVY, headersforeground="white",
            normalbackground="#081F33", normalforeground=TEXT_PRIMARY,
            weekendbackground="#EEF4FF", weekendforeground=TEXT_PRIMARY,
            othermonthbackground=NAVY, othermonthforeground="#60798F",
            othermonthweforeground="#60798F", othermonthwebackground=NAVY,
            selectbackground=PRIMARY_COLOR, selectforeground="white",
            bordercolor="#A78BFA", borderwidth=1, font=FONT_LABEL
        )
        cal.pack(padx=12, pady=12, fill="both", expand=True)

        def confirm():
            entry_widget.delete(0, "end")
            entry_widget.insert(0, cal.get_date())
            popup.destroy()

        ctk.CTkButton(popup, text="Select Date", width=200, height=38, corner_radius=19,
                      fg_color=PRIMARY_COLOR, hover_color=PRIMARY_HOVER, text_color="white",
                      font=FONT_BUTTON_SM, command=confirm).pack(pady=(0, 14))
        popup.update_idletasks()
        popup.lift()
        popup.focus_force()

    def _enable_mousewheel_scroll(self, scrollable_frame):
        """customtkinter's built-in mousewheel auto-binding can silently
        fail to catch scroll events on some platforms/builds. This binds
        it explicitly to the frame's own canvas so scrolling reliably
        works, and only while the cursor is actually over the widget
        (so it doesn't hijack scrolling elsewhere on the page)."""
        canvas = getattr(scrollable_frame, "_parent_canvas", None)
        if canvas is None:
            return

        SCROLL_SPEED = 4  # units per wheel notch — higher feels faster
        bound_widgets = [scrollable_frame, canvas]
        bound_widgets.extend(scrollable_frame.winfo_children())

        def _on_wheel(event):
            if getattr(event, "num", None) == 4:      # Linux scroll up
                canvas.yview_scroll(-SCROLL_SPEED, "units")
            elif getattr(event, "num", None) == 5:     # Linux scroll down
                canvas.yview_scroll(SCROLL_SPEED, "units")
            else:                                      # Windows / macOS
                delta = event.delta
                if not delta:
                    return
                # Touchpads emit smaller, high-resolution deltas than wheels.
                units = max(1, round(abs(delta) / 60))
                canvas.yview_scroll(-units if delta > 0 else units, "units")

        def _bind(_event=None):
            canvas.bind_all("<MouseWheel>", _on_wheel)
            canvas.bind_all("<Button-4>", _on_wheel)
            canvas.bind_all("<Button-5>", _on_wheel)

        def _unbind(_event=None):
            canvas.unbind_all("<MouseWheel>")
            canvas.unbind_all("<Button-4>")
            canvas.unbind_all("<Button-5>")

        for widget in bound_widgets:
            widget.bind("<Enter>", _bind, add="+")
            widget.bind("<Leave>", _unbind, add="+")
            widget.bind("<MouseWheel>", _on_wheel, add="+")
            widget.bind("<Button-4>", _on_wheel, add="+")
            widget.bind("<Button-5>", _on_wheel, add="+")

