    def register_user(self):
        name = self.reg_name.get().strip()
        email = self.reg_email.get().strip()
        password = self.reg_pass.get().strip()
        if not name or not email or not password:
            messagebox.showerror("Error", "All fields required")
            return
        email_lower = email.lower()
        if not email_lower.endswith("@gmail.com") or len(email_lower) <= len("@gmail.com"):
            messagebox.showerror("Error", "Please enter a valid Gmail address.")
            return
        try:
            self.db.register_user(name, email, password)
            messagebox.showinfo("Success", "Registered Successfully")
            self.login_page()
        except Exception as e:
            messagebox.showerror("Error", str(e))

