    def admin_login_user(self, button=None):
        """Admin login stays on the Tk/SQLite main thread.
        The previous worker-thread approach could trigger SQLite's
        same-thread connection error and make the admin page fail."""
        if getattr(self, "_admin_login_in_progress", False):
            return
        email = self.admin_login_email.get().strip()
        password = self.admin_login_pass.get().strip()
        if not email or not password:
            messagebox.showerror("Error", "Please enter admin email and password")
            return
        self._admin_login_in_progress = True
        if button is not None:
            button.configure(state="disabled", text="SIGNING IN...")
        try:
            user = self.db.login(email, password)
            if not user:
                messagebox.showerror("Login Failed", "Invalid admin email or password.")
                return
            if user[3] != "admin":
                messagebox.showerror("Access Denied", "This account does not have admin access.")
                return
            self.current_user = {"id":user[0],"name":user[1],"email":user[2],"role":user[3]}
            self.admin_dashboard()
        except Exception as error:
            messagebox.showerror("Database Error", f"Could not login:\n{error}")
        finally:
            self._admin_login_in_progress = False
            if button is not None:
                try:
                    button.configure(state="normal", text="ADMIN SIGN IN  🛡")
                except Exception:
                    pass

    def home_page(self):
        """Reference-style SkyBook Pro flight dashboard.

        Layout is intentionally kept close to the supplied reference image:
        navy sidebar, light-blue workspace, airplane hero, white flight-search
        card, compact feature cards, and no trending-destination section.
        Existing search/booking logic is preserved.
        """
        self.clear()
        self.configure(fg_color="#071A2A")

        root = ctk.CTkFrame(self, fg_color="transparent", corner_radius=0)
        root.place(x=0, y=0, relwidth=1, relheight=1)

        # ---------------- Home background wallpaper ----------------
        project_dir = os.path.dirname(os.path.abspath(__file__))
        bg_candidates = [
            # Dedicated Home wallpaper first.
            os.path.join(project_dir, "home_wallpaper.jpg"),
            os.path.join(project_dir, "home_wallpaper.png"),
            os.path.join(project_dir, "home_background.jpg"),
            os.path.join(project_dir, "home_background.png"),
            os.path.join(project_dir, "assets", "home_wallpaper.jpg"),
            os.path.join(project_dir, "assets", "home_wallpaper.png"),
            os.path.join(project_dir, "assets", "home_background.jpg"),
            os.path.join(project_dir, "assets", "home_background.png"),
            # Existing fallback wallpaper names.
            os.path.join(project_dir, "airplane.jpg"),
            os.path.join(project_dir, "airplane.png"),
            os.path.join(project_dir, "wallpaper.jpg"),
            os.path.join(project_dir, "wallpaper.png"),
            os.path.join(project_dir, "background.jpg"),
            os.path.join(project_dir, "background.png"),
            os.path.join(project_dir, "assets", "airplane.jpg"),
            os.path.join(project_dir, "assets", "airplane.png"),
        ]
        bg_candidates += [
            os.path.join(os.getcwd(), "home_wallpaper.jpg"),
            os.path.join(os.getcwd(), "home_wallpaper.png"),
            os.path.join(os.getcwd(), "assets", "home_wallpaper.jpg"),
            os.path.join(os.getcwd(), "assets", "home_wallpaper.png"),
        ]
        home_bg_path = next((x for x in bg_candidates if os.path.isfile(x)), None)
        self._home_bg_photo = None
