    def _home_mode(self, mode):
        """Handle the decorative service tabs on the home booking widget."""
        if mode == "Flights":
            return
        messagebox.showinfo(mode, f"{mode} booking will be available soon.")

    def toggle_trip_type(self, trip_type):
        """Show return date only for Round Trip; keep the home grid stable."""
        if trip_type == "One Way":
            self.return_box.grid_remove()
            self.selected_return_date = ""
        else:
            self.return_box.grid()
            self.selected_return_date = ""

    def suggest_airport(self, entry, combo):
        text = entry.get().strip().lower()
        results = [airport for airport in ALL_AIRPORTS if text in airport.lower()]
        combo.configure(values=results if results else ALL_AIRPORTS)
        if results:
            combo.set(results[0])

    @staticmethod
    def _resolve_airport(value):
        """Accept a full airport label, city name, or IATA code."""
        query = value.strip().lower()
        if not query:
            return None
        for airport in ALL_AIRPORTS:
            city, _, code = airport.partition("(")
            if query in {airport.lower(), city.strip().lower(), code.rstrip(") ").lower()}:
                return airport
        return next((airport for airport in ALL_AIRPORTS if query in airport.lower()), None)

    def swap_airports(self):
        source = self._resolve_airport(self.from_combo.get()) or self.from_combo.get().strip()
        destination = self._resolve_airport(self.to_combo.get()) or self.to_combo.get().strip()
        if not source or not destination:
            messagebox.showerror("Swap Error", "Please select both departure and arrival airports first.")
            return
        self.from_combo.set(destination)
        self.to_combo.set(source)

    def search_flights(self):
        self.fare_calendar_route = ""
        self.fare_calendar_date = ""
        self.fare_calendar_price = None
        self.fare_calendar_flight_no = ""
        self.selected_outbound_flight = None
        self.selected_return_flight = None
        self.selected_outbound_seats = []
        self.selected_return_seats = []
        self.selected_seats = []
        self._selecting_return_flight = False
        self._active_leg = "outbound"
        source = self._resolve_airport(self.from_combo.get())
        destination = self._resolve_airport(self.to_combo.get())
        if not source or not destination:
            messagebox.showerror("Search Error", "Please choose valid departure and arrival airports.")
            return
        if source == destination:
            messagebox.showerror("Error", "From and To airport cannot be the same")
            return

        travellers = self.travellers_combo.get().strip()
        if travellers.isdigit():
            n = int(travellers)
            travellers = f"{n} Member" if n == 1 else f"{n} Members"
        travel_class = self.class_combo.get()
        fare_type = self.fare_combo.get()
        valid_travellers = ["1 Member"] + [f"{count} Members" for count in range(2, 10)]
        valid_classes = ["Economy", "Premium Economy", "Business", "First Class"]
        valid_fares = ["Regular", "Student - 50% OFF", "Senior Citizen - 25% OFF", "Armed Forces - 30% OFF"]
        if travellers not in valid_travellers:
            messagebox.showerror("Error", "Please select a valid number of travellers")
            return
        if travel_class not in valid_classes:
            messagebox.showerror("Error", "Please select a valid class")
            return
        if fare_type not in valid_fares:
            messagebox.showerror("Error", "Please select a valid fare type")
            return

        self.selected_date = self.date_entry.get().strip()
        self.selected_return_date = ""
        is_round_trip = self.trip_type.get() == "Round Trip"
        try:
            departure_date = datetime.strptime(self.selected_date, "%d-%m-%Y").date()
            if is_round_trip:
                return_date = datetime.strptime(self.return_date_entry.get().strip(), "%d-%m-%Y")
        except ValueError:
            messagebox.showerror("Date Error", "Please enter valid departure and return dates.")
            return
        if departure_date < datetime.now().date():
            messagebox.showerror("Date Error", "Departure date cannot be in the past.")
            return
        if departure_date > (datetime.now() + timedelta(days=90)).date():
            messagebox.showerror("Date Error", "Flights can only be booked up to 3 months ahead.")
            return
        if is_round_trip:
            return_date = return_date.date()
            if return_date <= departure_date:
                messagebox.showerror("Date Error", "Return date must be after the departure date.")
                return
            if return_date > (datetime.now() + timedelta(days=90)).date():
                messagebox.showerror("Date Error", "Flights can only be booked up to 3 months ahead.")
                return
            self.selected_return_date = return_date.strftime("%d-%m-%Y")

        self.selected_route = f"{source} → {destination}"
        self.selected_travellers = travellers
        self.selected_class = travel_class
        self.selected_fare = fare_type
        try:
            flights = self.db.search_flights(source, destination)
        except Exception as error:
            flights = []
            print(f"Flight database search failed: {error}")
        if not flights:
            flights = self.temp_flights(source, destination)
        if flights:
            self.results_page(flights)
        else:
            messagebox.showerror("Search Error", "No flights are available for this route.")

    def temp_flights(self, source, destination):
        rows = []
        for airline in random.sample(AIRLINES, min(5, len(AIRLINES))):
            rows.append((
                "FL" + str(random.randint(1000, 9999)),
                airline, source, destination,
                f"{random.randint(5, 22):02d}:{random.choice([0,10,20,30,40,50]):02d}",
                f"{random.randint(1, 23):02d}:{random.choice([0,10,20,30,40,50]):02d}",
                f"{random.randint(2,9)}h {random.choice([10,20,30,45])}m",
                80, random.randint(6500, 36000), random.choice(["On Time", "Delayed"])
            ))
        return rows

    def results_page(self, flights):
        self.clear(); self.background(); self.topbar("Available Flights")
        header = ctk.CTkFrame(self, width=min(1120, self.screen_w - 40), height=76,
                              fg_color="#081F33", corner_radius=22,
                              border_width=1, border_color="#147DFF")
        header.pack(pady=(18, 8)); header.pack_propagate(False)
        is_return_selection = self._selecting_return_flight
        ctk.CTkLabel(header, text=self._t("Available Return Flights") if is_return_selection else self._t("Available Flights"), font=FONT_H3,
                     text_color=TEXT_PRIMARY).pack(side="left", padx=24, pady=16)
        date_label = self.selected_date
        if self.selected_return_date and not is_return_selection:
            date_label = f"{self.selected_date}  ⇄  {self.selected_return_date}"
        ctk.CTkLabel(header, text=f"{self.selected_route}  |  {date_label}  |  {self.selected_travellers}  |  {self.selected_class}",
                     font=FONT_SMALL_BOLD, text_color="#B7C9DC").pack(side="right", padx=24, pady=26)

        card_h, gap = 128, 16
        content_h = 20 + len(flights[:5]) * (card_h + gap)
        results_w = min(1120, self.screen_w - 40)
        box_w = results_w - 40
        viewport_h = min(content_h, self.screen_h - 250)

        outer_scroll = ctk.CTkScrollableFrame(self, width=results_w, height=viewport_h, fg_color="transparent",
                                              scrollbar_button_color="#147DFF")
        outer_scroll.pack(pady=16)
        self._enable_mousewheel_scroll(outer_scroll)

        box = ctk.CTkFrame(outer_scroll, width=box_w, height=content_h, fg_color="#081F33", corner_radius=28,
                           border_width=1, border_color="#B8D1E8")
        box.pack(); box.pack_propagate(False)
        for index, flight in enumerate(flights[:5]):
            self.flight_card(box, flight, index)

        ctk.CTkButton(self, text="←  " + self._t("Back to Search"), width=190, height=38, corner_radius=19,
                      fg_color="#103B5C", hover_color="#147DFF", border_width=1,
                      border_color="#00E5FF", text_color="#F3FAFF", font=FONT_BUTTON_SM,
                      command=self.home_page).pack()

    @staticmethod
    def _airport_code(label):
        if "(" in label and ")" in label:
            return label.split("(")[-1].split(")")[0]
        return label

    def show_fare_rules(self, fare_type, travel_class):
        rules = {
            "Regular": "Standard fare. Free cancellation up to 24 hours before departure; date changes attract a fee.",
            "Student - 50% OFF": "Valid student ID required at check-in. Ticket is non-transferable and refundable minus a small fee.",
            "Senior Citizen - 25% OFF": "Valid government age proof required. Priority boarding included; cancellation fee applies.",
            "Armed Forces - 30% OFF": "Valid service ID required at check-in. Extra 10 kg baggage allowance included."
        }
        baggage = {"Economy": "15 kg check-in / 7 kg cabin", "Premium Economy": "20 kg check-in / 7 kg cabin",
                   "Business": "30 kg check-in / 10 kg cabin", "First Class": "40 kg check-in / 10 kg cabin"}
        messagebox.showinfo(
            "Fare Rules",
            f"Fare type: {fare_type}\n{rules.get(fare_type, 'Standard fare rules apply.')}\n\n"
            f"Baggage ({travel_class}): {baggage.get(travel_class, '15 kg check-in / 7 kg cabin')}"
        )

    def _price_for_flight(self, flight_no, fare):
        price = final_price(fare, self.selected_class, self.selected_travellers, self.selected_fare)
        if (self.fare_calendar_price is not None
                and self.fare_calendar_route == self.selected_route
                and self.fare_calendar_date == self.selected_date
                and self.selected_class == "Economy"
                and self.selected_travellers == "1 Member"
                and self.selected_fare == "Regular"
                and self.fare_calendar_flight_no
                and str(flight_no).strip() == str(self.fare_calendar_flight_no).strip()):
            return int(self.fare_calendar_price)
        return int(price)

    def flight_card(self, parent, flight, index):
        flight_no, airline, source, dest, depart, arrive, duration, seats, fare, status = flight
        price = self._price_for_flight(flight_no, fare)
        card_h, gap = 128, 16
        y = 20 + index * (card_h + gap)
        card = ctk.CTkFrame(parent, width=parent.cget("width") - 80, height=card_h,
                    fg_color="#142A4A", corner_radius=20,
                    border_width=1, border_color="#B8D1E8")
        card.place(x=40, y=y)
        card_w = int(card.cget("width"))
        departure_x = max(190, int(card_w * 0.24))
        timeline_x = int(card_w * 0.36)
        arrival_x = int(card_w * 0.56)
        fare_x = int(card_w * 0.74)
        book_x = max(fare_x + 65, card_w - 175)

        status_colour = SUCCESS_COLOR if status.lower() == "on time" else ACCENT_COLOR

        # Airline + flight number + status pill
        ctk.CTkLabel(card, text=airline, font=FONT_H4, text_color=TEXT_PRIMARY).place(x=24, y=14)
        ctk.CTkLabel(card, text=flight_no, font=FONT_SMALL, text_color=TEXT_MUTED).place(x=24, y=44)
        ctk.CTkLabel(card, text=f"●  {self._t(status)}", font=FONT_SMALL_BOLD, text_color=status_colour).place(x=24, y=76)

        # Departure / duration timeline / arrival
        ctk.CTkLabel(card, text=depart, font=FONT_H3, text_color=TEXT_PRIMARY).place(x=departure_x, y=16)
        ctk.CTkLabel(card, text=self._airport_code(source), font=FONT_SMALL, text_color=TEXT_MUTED).place(x=departure_x, y=52)

        ctk.CTkFrame(card, width=150, height=2, fg_color="#35E0FF").place(x=timeline_x, y=32)
        ctk.CTkLabel(card, text="✈", font=FONT_EMOJI_SM, text_color=ACCENT_COLOR).place(x=timeline_x + 68, y=8)
        ctk.CTkLabel(card, text=duration, font=FONT_SMALL, text_color=TEXT_MUTED).place(x=timeline_x + 18, y=42)
        ctk.CTkLabel(card, text=f"{seats} {self._t('seats left')}", font=FONT_TINY, text_color="#C4B5FD").place(x=timeline_x + 18, y=60)

        ctk.CTkLabel(card, text=arrive, font=FONT_H3, text_color=TEXT_PRIMARY).place(x=arrival_x, y=16)
        ctk.CTkLabel(card, text=self._airport_code(dest), font=FONT_SMALL, text_color=TEXT_MUTED).place(x=arrival_x, y=52)

        # Fare rules + price + book button
        ctk.CTkButton(card, text=self._t("View Fare Rules"), width=130, height=24, corner_radius=12,
                  fg_color="#103B5C", hover_color="#147DFF", border_width=1, border_color="#35E0FF",
                  text_color="#E8F7FF", font=FONT_TINY,
                      command=lambda: self.show_fare_rules(self.selected_fare, self.selected_class)).place(x=fare_x, y=14)
        ctk.CTkLabel(card, text=f"₹{price}", font=FONT_H2, text_color=TEXT_PRIMARY).place(x=fare_x, y=42)
        ctk.CTkButton(card, text=self._t("BOOK NOW  →"), width=150, height=38, corner_radius=19, fg_color="#FACC15",
                  hover_color="#EAB308", text_color="#F3FAFF", font=FONT_BUTTON_SM,
                      command=lambda: self.select_flight(flight_no, airline, price)).place(x=book_x, y=80)

    def select_flight(self, flight_no, airline, price):
        if self.selected_return_date and not self._selecting_return_flight:
            source, _, destination = self.selected_route.partition(" → ")
            self.selected_outbound_flight = {
                "flight_no": str(flight_no).strip(),
                "airline": str(airline).strip(),
                "price": int(price),
                "route": self.selected_route,
                "date": self.selected_date
            }
            self._selecting_return_flight = True
            self.selected_route = f"{destination} → {source}"
            self.selected_date = self.selected_return_date
            try:
                return_flights = self.db.search_flights(destination, source)
            except Exception as error:
                return_flights = []
                print(f"Return flight database search failed: {error}")
            if not return_flights:
                return_flights = self.temp_flights(destination, source)
            self.results_page(return_flights)
            return

        if self._selecting_return_flight:
            self.selected_return_flight = {
                "flight_no": str(flight_no).strip(),
                "airline": str(airline).strip(),
                "price": int(price),
                "route": self.selected_route,
                "date": self.selected_date
            }
            self._selecting_return_flight = False
            self.selected_route = self.selected_outbound_flight["route"]
            self.selected_date = self.selected_outbound_flight["date"]
            self.selected_flight = self.selected_outbound_flight["flight_no"]
            self.selected_airline = self.selected_outbound_flight["airline"]
            self.selected_price = self.selected_outbound_flight["price"] + self.selected_return_flight["price"]
        else:
            self.selected_flight = str(flight_no).strip()
            self.selected_airline = str(airline).strip()
            self.selected_price = int(price)
        self.selected_seats = []
        self.selected_outbound_seats = []
        self.selected_return_seats = []
        self._active_leg = "outbound"
        self.selected_passenger_name = self.current_user.get("name", "").strip() if self.current_user else ""
        self.selected_passenger_names = [self.selected_passenger_name] if self.selected_passenger_name else []
        self.selected_passenger_details = []
        self.selected_mobile = ""
        try:
            self.passenger_details_page()
        except Exception as error:
            messagebox.showerror("Passenger Details Error", f"Could not open passenger details:\n{error}")

    def passenger_details_page(self):
        if not self.current_user or not self.selected_flight or self.selected_price <= 0:
            messagebox.showerror("Booking Error", "Select a flight with a valid fare before entering passenger details.")
            self.home_page()
            return

        self.clear(); self.background(); self.topbar("Passenger Details")
        traveller_count = self._required_seat_count()
        card_height = min(max(680, 420 + traveller_count * 70), self.screen_h - 100)
        card = self.app_card(650, card_height, rely=0.54)
        ctk.CTkLabel(card, text="PASSENGER DETAILS", font=FONT_H1,
                     text_color=TEXT_PRIMARY).pack(pady=(34, 8))
        itinerary_summary = (
            f"Outbound: {self.selected_airline} · {self.selected_flight}\n"
            f"{self.selected_route}\nTravel date: {self.selected_date}"
        )
        if self.selected_return_flight:
            itinerary_summary += (
                f"\nReturn: {self.selected_return_flight['airline']} · {self.selected_return_flight['flight_no']}"
                f"\n{self.selected_return_flight['route']} · {self.selected_return_date}"
            )
        itinerary_summary += f"\nTotal fare: ₹{self.selected_price:,}"
        ctk.CTkLabel(
            card,
            text=itinerary_summary,
            font=FONT_BODY, text_color=TEXT_MUTED, justify="center"
        ).pack(pady=(0, 22))

        passenger_field_style = {
            "fg_color": "#132B47", "border_color": "#147DFF",
            "text_color": TEXT_PRIMARY, "placeholder_text_color": "#A8BCD0"
        }
        passenger_combo_style = {
            "fg_color": "#132B47", "border_color": "#147DFF",
            "text_color": TEXT_PRIMARY, "button_color": "#147DFF",
            "button_hover_color": "#0B68C7"
        }
        form_height = min(max(360, traveller_count * 260 + 60), max(360, card_height - 330))
        passenger_form = ctk.CTkScrollableFrame(
            card, width=500, height=form_height, fg_color="transparent"
        )
        passenger_form.pack(fill="x", padx=50, pady=(0, 8))
        self.passenger_name_entries = []
        self.passenger_dob_entries = []
        self.passenger_age_entries = []
        self.passenger_gender_boxes = []
        self.passenger_mobile_entries = []
        self.passenger_email_entries = []
        self.passenger_id_type_boxes = []
        self.passenger_id_number_entries = []
        self.passenger_nationality_entries = []
        form_input_widgets = []
        saved_names = list(self.selected_passenger_names)
        if not saved_names and self.selected_passenger_name:
            saved_names = [self.selected_passenger_name]
        for index in range(traveller_count):
            saved_details = self.selected_passenger_details[index] if index < len(self.selected_passenger_details) else {}
            ctk.CTkLabel(passenger_form, text=f"PASSENGER {index + 1}",
                         font=FONT_BODY_BOLD, text_color=TEXT_PRIMARY,
                         width=430, anchor="w").pack(pady=(8, 2))
            ctk.CTkLabel(passenger_form, text="FULL NAME",
                         font=FONT_TINY_BOLD, text_color=TEXT_MUTED,
                         width=430, anchor="w").pack()
            name_entry = ctk.CTkEntry(
                passenger_form, placeholder_text=f"Traveller {index + 1} Full Name",
                width=430, height=44, **passenger_field_style
            )
            name_entry.pack(pady=7)
            if index < len(saved_names):
                name_entry.insert(0, saved_names[index])
            self.passenger_name_entries.append(name_entry)
            form_input_widgets.append(name_entry)

            ctk.CTkLabel(passenger_form, text="DATE OF BIRTH (DD-MM-YYYY)  /  AGE",
                         font=FONT_TINY_BOLD, text_color=TEXT_MUTED,
                         width=430, anchor="w").pack()
            birth_age_row = ctk.CTkFrame(passenger_form, fg_color="transparent")
            birth_age_row.pack(pady=7)
            dob_entry = ctk.CTkEntry(
                birth_age_row, placeholder_text="DD-MM-YYYY", width=300, height=44,
                **passenger_field_style
            )
            dob_entry.pack(side="left", padx=(0, 8))
            dob_entry.insert(0, saved_details.get("date_of_birth", ""))
            age_entry = ctk.CTkEntry(
                birth_age_row, placeholder_text="Age", width=120, height=44,
                state="disabled", **passenger_field_style
            )
            age_entry.pack(side="left")
            self.passenger_dob_entries.append(dob_entry)
            self.passenger_age_entries.append(age_entry)
            form_input_widgets.append(dob_entry)

            def update_age(_event=None, traveller_index=index):
                date_text = self.passenger_dob_entries[traveller_index].get().strip()
                try:
                    birth_date = datetime.strptime(date_text, "%d-%m-%Y").date()
                    today = datetime.now().date()
                    age = today.year - birth_date.year - (
                        (today.month, today.day) < (birth_date.month, birth_date.day)
                    )
                    age_text = str(age) if birth_date <= today else ""
                except ValueError:
                    age_text = ""
                age_widget = self.passenger_age_entries[traveller_index]
                age_widget.configure(state="normal")
                age_widget.delete(0, "end")
                age_widget.insert(0, age_text)
                age_widget.configure(state="disabled")

            dob_entry.bind("<FocusOut>", update_age)
            if saved_details.get("date_of_birth"):
                update_age()

            ctk.CTkLabel(passenger_form, text="GENDER", font=FONT_TINY_BOLD,
                         text_color=TEXT_MUTED, width=430, anchor="w").pack()
            gender_box = ctk.CTkComboBox(
                passenger_form,
                values=["Female", "Male", "Non-binary", "Other", "Prefer not to say"],
                width=430, height=44, **passenger_combo_style
            )
            gender_box.set(saved_details.get("gender", "Select gender"))
            gender_box.pack(pady=7)
            self.passenger_gender_boxes.append(gender_box)
            form_input_widgets.append(gender_box)

            passenger_fields = [
                ("MOBILE NUMBER", "10-digit Mobile Number", "mobile", "entry"),
                ("EMAIL ADDRESS", "name@example.com", "email", "entry"),
            ]
            for label_text, placeholder, detail_key, _field_kind in passenger_fields:
                ctk.CTkLabel(passenger_form, text=label_text, font=FONT_TINY_BOLD,
                             text_color=TEXT_MUTED, width=430, anchor="w").pack()
                field = ctk.CTkEntry(
                    passenger_form, placeholder_text=placeholder, width=430, height=44,
                    **passenger_field_style
                )
                field.pack(pady=7)
                field.insert(0, saved_details.get(detail_key, ""))
                form_input_widgets.append(field)
                if detail_key == "mobile":
                    self.passenger_mobile_entries.append(field)
                else:
                    self.passenger_email_entries.append(field)

            ctk.CTkLabel(passenger_form, text="ID PROOF TYPE", font=FONT_TINY_BOLD,
                         text_color=TEXT_MUTED, width=430, anchor="w").pack()
            id_type_box = ctk.CTkComboBox(
                passenger_form,
                values=["Aadhaar", "Passport", "Driving Licence"],
                width=430, height=44, **passenger_combo_style
            )
            id_type_box.set(saved_details.get("id_proof_type", "Select ID proof type"))
            id_type_box.pack(pady=7)
            self.passenger_id_type_boxes.append(id_type_box)
            form_input_widgets.append(id_type_box)

            ctk.CTkLabel(passenger_form, text="ID PROOF NUMBER", font=FONT_TINY_BOLD,
                         text_color=TEXT_MUTED, width=430, anchor="w").pack()
            id_number_entry = ctk.CTkEntry(
                passenger_form, placeholder_text="ID Proof Number", width=430, height=44,
                **passenger_field_style
            )
            id_number_entry.pack(pady=7)
            id_number_entry.insert(0, saved_details.get("id_proof_number", ""))
            self.passenger_id_number_entries.append(id_number_entry)
            form_input_widgets.append(id_number_entry)

            ctk.CTkLabel(passenger_form, text="NATIONALITY", font=FONT_TINY_BOLD,
                         text_color=TEXT_MUTED, width=430, anchor="w").pack()
            nationality_entry = ctk.CTkEntry(
                passenger_form, placeholder_text="Nationality", width=430, height=44,
                **passenger_field_style
            )
            nationality_entry.pack(pady=7)
            nationality_entry.insert(0, saved_details.get("nationality", ""))
            self.passenger_nationality_entries.append(nationality_entry)
            form_input_widgets.append(nationality_entry)

        def continue_to_seats():
            passenger_names = [entry.get().strip() for entry in self.passenger_name_entries]
            passenger_details = []
            for index, passenger_name in enumerate(passenger_names):
                if not passenger_name:
                    messagebox.showerror("Passenger Details", f"Please enter the full name for passenger {index + 1}.")
                    self.passenger_name_entries[index].focus_set()
                    return
                date_text = self.passenger_dob_entries[index].get().strip()
                try:
                    birth_date = datetime.strptime(date_text, "%d-%m-%Y").date()
                except ValueError:
                    messagebox.showerror("Passenger Details", f"Enter a valid date of birth for passenger {index + 1} (DD-MM-YYYY).")
                    self.passenger_dob_entries[index].focus_set()
                    return
                today = datetime.now().date()
                if birth_date > today:
                    messagebox.showerror("Passenger Details", f"Date of birth cannot be in the future for passenger {index + 1}.")
                    self.passenger_dob_entries[index].focus_set()
                    return
                gender = self.passenger_gender_boxes[index].get().strip()
                if gender not in {"Female", "Male", "Non-binary", "Other", "Prefer not to say"}:
                    messagebox.showerror("Passenger Details", f"Select a gender for passenger {index + 1}.")
                    self.passenger_gender_boxes[index].focus_set()
                    return
                mobile = self.passenger_mobile_entries[index].get().strip()
                if not mobile.isdigit() or len(mobile) != 10:
                    messagebox.showerror("Passenger Details", f"Enter a valid 10 digit mobile number for passenger {index + 1}.")
                    self.passenger_mobile_entries[index].focus_set()
                    return
                email = self.passenger_email_entries[index].get().strip()
                if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
                    messagebox.showerror("Passenger Details", f"Enter a valid email address for passenger {index + 1}.")
                    self.passenger_email_entries[index].focus_set()
                    return
                id_proof_type = self.passenger_id_type_boxes[index].get().strip()
                if id_proof_type not in {"Aadhaar", "Passport", "Driving Licence"}:
                    messagebox.showerror("Passenger Details", f"Select an ID proof type for passenger {index + 1}.")
                    self.passenger_id_type_boxes[index].focus_set()
                    return
                id_proof_number = self.passenger_id_number_entries[index].get().strip().upper()
                if id_proof_type == "Aadhaar":
                    id_proof_number = re.sub(r"\s+", "", id_proof_number)
                if id_proof_type == "Aadhaar":
                    valid_id_number = bool(re.fullmatch(r"\d{12}", id_proof_number))
                elif id_proof_type == "Passport":
                    valid_id_number = bool(re.fullmatch(r"[A-Z0-9]{6,20}", id_proof_number))
                else:
                    valid_id_number = bool(re.fullmatch(r"[A-Z0-9/-]{6,20}", id_proof_number))
                if not valid_id_number:
                    messagebox.showerror("Passenger Details", f"Enter a valid {id_proof_type} number for passenger {index + 1}.")
                    self.passenger_id_number_entries[index].focus_set()
                    return
                nationality = self.passenger_nationality_entries[index].get().strip()
                if not nationality:
                    messagebox.showerror("Passenger Details", f"Enter the nationality for passenger {index + 1}.")
                    self.passenger_nationality_entries[index].focus_set()
                    return
                age = today.year - birth_date.year - (
                    (today.month, today.day) < (birth_date.month, birth_date.day)
                )
                passenger_details.append({
                    "full_name": passenger_name,
                    "date_of_birth": birth_date.strftime("%d-%m-%Y"),
                    "age": age,
                    "gender": gender,
                    "mobile": mobile,
                    "email": email,
                    "id_proof_type": id_proof_type,
                    "id_proof_number": id_proof_number,
                    "nationality": nationality,
                })
            self.selected_passenger_names = passenger_names
            self.selected_passenger_name = ", ".join(passenger_names)
            self.selected_passenger_details = passenger_details
            self.selected_mobile = passenger_details[0]["mobile"]
            self.seat_page()

        for index, widget in enumerate(form_input_widgets):
            if index + 1 < len(form_input_widgets):
                widget.bind("<Return>", lambda _event, target=form_input_widgets[index + 1]: target.focus_set())
        if form_input_widgets:
            form_input_widgets[-1].bind("<Return>", lambda _event: continue_to_seats())
        ctk.CTkButton(
            card, text="Continue to Seat Selection  →", width=360, height=44,
            fg_color=PRIMARY_COLOR, hover_color=PRIMARY_HOVER,
            command=continue_to_seats
        ).pack(pady=(22, 8))
        ctk.CTkButton(card, text="Back to Search", width=180,
                      command=self.home_page).pack()

    def _required_seat_count(self):
        """How many seats need to be picked, based on '2 Adults' etc."""
        try:
            return max(1, int(str(self.selected_travellers).split()[0]))
        except Exception:
            return 1

    def _passenger_details_complete(self):
        if len(self.selected_passenger_details) != self._required_seat_count():
            return False

        for detail in self.selected_passenger_details:
            if not all(detail.get(key) for key in (
                "full_name", "date_of_birth", "gender", "mobile", "email",
                "id_proof_type", "id_proof_number", "nationality"
            )):
                return False
            if detail["gender"] not in {"Female", "Male", "Non-binary", "Other", "Prefer not to say"}:
                return False
            if not re.fullmatch(r"\d{10}", detail["mobile"]):
                return False
            if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", detail["email"]):
                return False
            try:
                birth_date = datetime.strptime(detail["date_of_birth"], "%d-%m-%Y").date()
            except ValueError:
                return False
            if birth_date > datetime.now().date():
                return False

            id_type = detail["id_proof_type"]
            id_number = detail["id_proof_number"]
            if id_type == "Aadhaar":
                valid_id = bool(re.fullmatch(r"\d{12}", id_number))
            elif id_type == "Passport":
                valid_id = bool(re.fullmatch(r"[A-Z0-9]{6,20}", id_number))
            elif id_type == "Driving Licence":
                valid_id = bool(re.fullmatch(r"[A-Z0-9/-]{6,20}", id_number))
            else:
                valid_id = False
            if not valid_id:
                return False
        return True

    def _continue_after_seat_selection(self):
        if self.selected_return_flight and self._active_leg == "outbound":
            self._active_leg = "return"
            self.seat_page()
            return
        self.payment_page()

    def seat_page(self):
        self.clear(); self.background(); self.topbar("Premium Seat Selection")
        self._seat_buttons = {}
        required = self._required_seat_count()
        is_return_leg = bool(self.selected_return_flight and self._active_leg == "return")
        active_flight = self.selected_return_flight if is_return_leg else {
            "flight_no": self.selected_flight,
            "airline": self.selected_airline,
            "route": self.selected_route,
            "date": self.selected_date,
            "price": self.selected_outbound_flight["price"] if self.selected_outbound_flight else self.selected_price
        }
        self.selected_seats = self.selected_return_seats if is_return_leg else self.selected_outbound_seats

        rows = list(range(1, 15))                    # 14 rows
        cols = ["A", "B", "C", "D", "E", "F"]         # classic 3-3 layout: ABC | DEF
        total_seats = len(rows) * len(cols)
        try:
            booked = self.db.booked_seats(active_flight["flight_no"], active_flight["date"])
        except Exception as error:
            print(f"Booked-seat lookup failed: {error}")
            booked = []
        self.selected_seats = [seat for seat in self.selected_seats if seat not in booked]
        if is_return_leg:
            self.selected_return_seats = self.selected_seats
        else:
            self.selected_outbound_seats = self.selected_seats

        outer_w = min(self.screen_w - 40, 1120)
        outer_h = min(self.screen_h - 92, 760)
        shell = ctk.CTkFrame(self, width=outer_w, height=outer_h, fg_color="#081F33",
                 corner_radius=30, border_width=1, border_color="#147DFF")
        shell.place(relx=0.5, rely=0.54, anchor="center")
        shell.pack_propagate(False)

        ctk.CTkLabel(shell, text=f"{active_flight['airline']} | {active_flight['flight_no']} | {active_flight['route']} | {active_flight['date']} | ₹{active_flight['price']}",
                 font=FONT_H4, text_color=TEXT_PRIMARY).pack(pady=(14, 1))
        status_label = ctk.CTkLabel(shell, text=f"Select {required} seat(s) for {self.selected_travellers}",
                        font=FONT_SUBTITLE_BOLD, text_color=ACCENT_COLOR)
        status_label.pack(pady=(0, 8))

        map_header = ctk.CTkFrame(shell, height=54, fg_color="#147DFF", corner_radius=18,
                      border_width=1, border_color="#00E5FF")
        map_header.pack(fill="x", padx=18, pady=(0, 8)); map_header.pack_propagate(False)
        ctk.CTkLabel(map_header, text=f"✈  AIRBUS A320 • {total_seats} SEATS", font=FONT_H3,
                 text_color="#F3FAFF").pack(side="left", padx=20, pady=8)
        ctk.CTkLabel(map_header, text="Choose a window or aisle seat", font=FONT_SMALL,
                 text_color="#E8F7FF").pack(side="right", padx=20)

        # Reserve space for the flight header, status text, and footer actions.
        map_h = max(160, outer_h - 300)
        map_scroll = ctk.CTkScrollableFrame(shell, height=map_h, fg_color="#061827",
                            corner_radius=22, scrollbar_button_color="#147DFF")
        map_scroll.pack(fill="x", padx=18, pady=(0, 8))
        self._enable_mousewheel_scroll(map_scroll)

        body = ctk.CTkFrame(map_scroll, fg_color="transparent")
        body.pack(pady=10)
        plane_w = min(700, max(360, outer_w - 270))
        plane = ctk.CTkFrame(body, width=plane_w, height=570, fg_color="#103B5C", corner_radius=32,
                     border_width=1, border_color="#147DFF")
        plane.pack(side="left", padx=(0, 12)); plane.pack_propagate(False)
        ctk.CTkLabel(plane, text="COCKPIT", font=FONT_BUTTON_SM, text_color="#00E5FF").pack(pady=(10, 2))

        grid = ctk.CTkFrame(plane, fg_color="transparent")
        grid.pack(pady=4)

        actions = ctk.CTkFrame(shell, fg_color="transparent")
        actions.place(relx=0.5, rely=1.0, anchor="s", y=-12)
        continue_btn = ctk.CTkButton(actions, text=f"Select {required} more seat(s)", width=290, height=40,
                         corner_radius=20, fg_color="#50677D", text_color="#F3FAFF", state="disabled",
                         font=FONT_BUTTON_SM, command=self._continue_after_seat_selection)

        def refresh_status():
            picked = len(self.selected_seats)
            if picked < required:
                status_label.configure(text=f"Select {required - picked} more seat(s) for {self.selected_travellers}")
                continue_btn.configure(text=f"Select {required - picked} more seat(s)",
                                       state="disabled", fg_color="#50677D", text_color="#F3FAFF")
            else:
                status_label.configure(text=f"All set — {', '.join(self.selected_seats)} selected")
                next_action = "Continue to Return Flight Seats" if self.selected_return_flight and self._active_leg == "outbound" else f"Continue to Payment ({picked} seat{'s' if picked != 1 else ''})"
                continue_btn.configure(text=next_action,
                                       state="normal", fg_color=PRIMARY_COLOR, hover_color=PRIMARY_HOVER, text_color="white")
            selected_label.configure(text=f"Selected: {', '.join(self.selected_seats) if self.selected_seats else 'None'}")

        def toggle_seat(seat):
            btn = self._seat_buttons[seat]
            if seat in self.selected_seats:
                self.selected_seats.remove(seat)
                btn.configure(fg_color=GREEN_COLOR, hover_color="#16a34a", text_color="white")
            elif len(self.selected_seats) >= required:
                messagebox.showinfo("Seat Limit", f"You can only select {required} seat(s) for {self.selected_travellers}.")
                return
            else:
                self.selected_seats.append(seat)
                btn.configure(fg_color=PRIMARY_COLOR, hover_color=PRIMARY_HOVER, text_color="white")
            refresh_status()

        for r, rownum in enumerate(rows):
            ctk.CTkLabel(grid, text=str(rownum), width=22, font=FONT_LABEL_BOLD,
                         text_color="#EDE9FE").grid(row=r, column=0, padx=(0, 6), pady=3)
            for c, col in enumerate(cols):
                seat = f"{col}{rownum}"
                is_booked = seat in booked
                gap = (18 if c == 3 else 4, 4)   # real aisle: ABC | DEF
                seat_btn = ctk.CTkButton(
                    grid, text=seat, width=48, height=28, corner_radius=10,
                    fg_color=ERROR_COLOR if is_booked else PRIMARY_COLOR if seat in self.selected_seats else GREEN_COLOR,
                    hover_color=PRIMARY_HOVER if seat in self.selected_seats else "#16a34a", text_color="white",
                    font=FONT_SMALL_BOLD,
                    state="disabled" if is_booked else "normal",
                    command=lambda s=seat: toggle_seat(s)
                )
                seat_btn.grid(row=r, column=c + 1, padx=gap, pady=3)
                if not is_booked:
                    self._seat_buttons[seat] = seat_btn

        # --- seat guide side panel ---
        legend_panel = ctk.CTkFrame(body, width=196, height=570, fg_color="#081F33",
                corner_radius=24, border_width=1, border_color="#147DFF")
        legend_panel.pack(side="left"); legend_panel.pack_propagate(False)
        ctk.CTkLabel(legend_panel, text="SEAT GUIDE", font=FONT_BUTTON_SM,
                 text_color="#DDF7FF").pack(pady=(18, 10))

        def legend_row(colour, text):
            row = ctk.CTkFrame(legend_panel, fg_color="transparent")
            row.pack(anchor="w", padx=20, pady=5)
            ctk.CTkFrame(row, width=16, height=16, corner_radius=8, fg_color=colour).grid(row=0, column=0)
            ctk.CTkLabel(row, text=text, font=FONT_SMALL, text_color="white").grid(row=0, column=1, padx=8)

        legend_row(GREEN_COLOR, "Available")
        legend_row(ERROR_COLOR, "Booked")
        legend_row(ACCENT_COLOR, "Selected")

        divider = ctk.CTkFrame(legend_panel, width=156, height=1, fg_color="#50677D")
        divider.pack(pady=12)

        available_count = total_seats - len(booked)
        ctk.CTkLabel(legend_panel, text=str(available_count), font=FONT_H1,
                     text_color=TEXT_PRIMARY).pack()
        ctk.CTkLabel(legend_panel, text="seats available", font=FONT_SMALL,
                     text_color=TEXT_MUTED).pack(pady=(0, 12))
        selected_label = ctk.CTkLabel(legend_panel, text="Selected: None", font=FONT_SMALL_BOLD,
                                      text_color="#00E5FF", wraplength=160)
        selected_label.pack(padx=12, pady=(0, 10))
        refresh_status()
        ctk.CTkLabel(legend_panel, text="✈ ABC | Aisle | DEF", font=FONT_TINY,
                     text_color="#A9DCEB").pack()

        if outer_w < 850:
            continue_btn.pack(pady=(0, 6))
            ctk.CTkButton(actions, text="← Back to Search", width=290, height=40, corner_radius=20,
                          fg_color="#103B5C", hover_color="#147DFF", border_width=1,
                          border_color="#00E5FF", text_color="#F3FAFF",
                          command=self.home_page).pack()
        else:
            continue_btn.pack(side="left", padx=6)
            ctk.CTkButton(actions, text="← Back to Search", width=180, height=40, corner_radius=20,
                          fg_color="#103B5C", hover_color="#147DFF", border_width=1,
                          border_color="#00E5FF", text_color="#F3FAFF",
                          command=self.home_page).pack(side="left", padx=6)
        actions.lift()

    def payment_page(self):
        if (not self.current_user or not self.selected_flight
                or not self.selected_route or not self.selected_date
                or int(self.selected_price or 0) <= 0):
            messagebox.showerror("Booking Error", "Select a flight with a valid fare before payment.")
            self.home_page()
            return
        if (len(self.selected_passenger_names) != self._required_seat_count()
            or not all(name.strip() for name in self.selected_passenger_names)
            or not self._passenger_details_complete()
            or not self.selected_mobile.strip()):
            messagebox.showerror("Passenger Details", "Complete passenger details before payment.")
            self.passenger_details_page()
            return
        seat_legs = [(self.selected_seats, "flight")]
        if self.selected_return_flight:
            seat_legs = [
                (self.selected_outbound_seats, "outbound flight"),
                (self.selected_return_seats, "return flight")
            ]
        for seats, leg_name in seat_legs:
            if len(seats) != self._required_seat_count():
                messagebox.showerror("Seat Selection", f"Select the required number of seats for the {leg_name}.")
                self._active_leg = "return" if leg_name == "return flight" else "outbound"
                self.seat_page()
                return
        self._booking_in_progress = False
        self.clear(); self.background(); self.topbar("Payment")
        card = self.app_card(650, 620, rely=0.54)
        ctk.CTkLabel(card, text="SECURE CHECKOUT", font=FONT_TINY_BOLD,
                     text_color="#35E0FF").pack(pady=(22, 4))
        ctk.CTkLabel(card, text="Payment Details", font=FONT_H1,
                     text_color="#F3FAFF").pack()
        ctk.CTkLabel(card, text="Complete your booking securely and receive your e-ticket instantly",
                     font=FONT_BODY, text_color=TEXT_MUTED).pack(pady=(5, 16))
        seats_text = ", ".join(self.selected_outbound_seats if self.selected_return_flight else self.selected_seats)
        date_text = self.selected_date
        if self.selected_return_date:
            date_text = f"{self.selected_date}  ⇄  {self.selected_return_date}"
        details = f"Passenger: {self.selected_passenger_name}\nOutbound: {self.selected_airline} | {self.selected_flight} | {self.selected_route}\nDate: {date_text}\nSeat(s): {seats_text}"
        if self.selected_return_flight:
            details += (
                f"\nReturn: {self.selected_return_flight['airline']} | {self.selected_return_flight['flight_no']}"
                f" | {self.selected_return_flight['route']}\nReturn seat(s): {', '.join(self.selected_return_seats)}"
            )
        details += f"\nClass: {self.selected_class}\nAmount: ₹{self.selected_price:,}"
        details += f"\nContact mobile: {self.selected_mobile}"
        summary = ctk.CTkFrame(card, width=500, height=190 if self.selected_return_flight else 142, fg_color="#081F33",
                               corner_radius=18, border_width=1, border_color="#B8D1E8")
        summary.pack(pady=(0, 14)); summary.pack_propagate(False)
        ctk.CTkLabel(summary, text=details, font=FONT_BODY, text_color="#E8F7FF",
                     justify="center").pack(expand=True)

        payment_form = ctk.CTkFrame(card, fg_color="transparent")
        payment_form.pack()
        field_style = {
            "fg_color": "#132B47", "border_color": "#147DFF",
            "text_color": TEXT_PRIMARY, "placeholder_text_color": "#7189A3"
        }
        self.payment_method = ctk.CTkComboBox(payment_form,
                                              values=["UPI", "Debit Card", "Credit Card", "Net Banking"],
                                              width=430, height=44, corner_radius=22,
                                              font=FONT_BODY, dropdown_font=FONT_BODY,
                                              fg_color="#132B47", border_color="#147DFF",
                                              button_color="#147DFF", button_hover_color="#00E5FF",
                                              text_color=TEXT_PRIMARY, dropdown_fg_color="#081F33",
                                              dropdown_hover_color="#103B5C", dropdown_text_color=TEXT_PRIMARY)
        self.payment_method.set("UPI"); self.payment_method.pack(pady=6)
        self.payment_ref = ctk.CTkEntry(payment_form,
                                        placeholder_text="UPI ID / Card Number / Reference",
                                        width=430, height=44, corner_radius=22,
                                        font=FONT_BODY, **field_style)
        self.payment_ref.pack(pady=6)
        pay_btn = ctk.CTkButton(payment_form, text="PAY & CONFIRM  ✓", width=430, height=48,
                      corner_radius=24, fg_color=SUCCESS_COLOR, hover_color=SUCCESS_HOVER,
                      font=FONT_SUBTITLE_BOLD)
        pay_btn.configure(command=lambda: self.confirm_ticket(pay_btn))
        self.payment_ref.bind("<Return>", lambda e: self.confirm_ticket(pay_btn))
        pay_btn.pack(pady=(12, 8))
        ctk.CTkButton(payment_form, text="← Back to Seats", width=190, height=34,
                      corner_radius=17, fg_color="#103B5C", hover_color="#147DFF",
                      border_width=1, border_color="#B8D1E8", font=FONT_SMALL_BOLD,
                      command=self.seat_page).pack()

    def confirm_ticket(self, button=None):
        if getattr(self, "_booking_in_progress", False):
            return  # PAY & CONFIRM already handled a click — ignore repeats (double-click, double Enter, etc.)
        if (not self.current_user or not self.selected_flight
                or not self.selected_route or not self.selected_date
                or int(self.selected_price or 0) <= 0):
            messagebox.showerror("Booking Error", "No valid flight and fare are selected.")
            self.home_page()
            return
        try:
            departure_date = datetime.strptime(self.selected_date, "%d-%m-%Y").date()
            if self.selected_return_date:
                return_date = datetime.strptime(self.selected_return_date, "%d-%m-%Y").date()
        except ValueError:
            messagebox.showerror("Date Error", "Enter valid departure and return dates before payment.")
            return
        if departure_date < datetime.now().date():
            messagebox.showerror("Date Error", "Departure date has passed. Please search again.")
            return
        latest_booking_date = (datetime.now() + timedelta(days=90)).date()
        if departure_date > latest_booking_date or (self.selected_return_date and return_date > latest_booking_date):
            messagebox.showerror("Date Error", "Flights can only be booked up to 3 months ahead.")
            return
        if self.selected_return_date and return_date <= departure_date:
            messagebox.showerror("Date Error", "Return date must be after the departure date.")
            return
        if self.selected_return_date and not self.selected_return_flight:
            messagebox.showerror("Flight Selection", "Select a return flight before continuing.")
            return
        passenger_name = ", ".join(self.selected_passenger_names).strip()
        if (len(self.selected_passenger_names) != self._required_seat_count()
                or not all(name.strip() for name in self.selected_passenger_names)
                or not self._passenger_details_complete()):
            messagebox.showerror("Passenger Details", "Enter a full name for every traveller before payment.")
            self.passenger_details_page()
            return
        mobile = self.selected_mobile.strip()
        payment_details = self.payment_ref.get().strip()

        if not passenger_name:
            messagebox.showerror("Passenger Details", "Please enter passenger details before payment.")
            self.passenger_details_page()
            return

        if not mobile:
            messagebox.showerror("Error", "Please enter a mobile number")
            return
        if not mobile.isdigit() or len(mobile) != 10:
            messagebox.showerror("Error", "Please enter a valid 10 digit mobile number")
            return
        if not payment_details:
            messagebox.showerror("Error", "Please enter payment details")
            return
        method = self.payment_method.get().strip()
        if method not in {"UPI", "Debit Card", "Credit Card", "Net Banking"}:
            messagebox.showerror("Error", "Please select a supported payment method.")
            return
        if method == "UPI" and not re.fullmatch(r"[A-Za-z0-9._-]+@[A-Za-z]+", payment_details):
            messagebox.showerror("Error", "Please enter a valid UPI ID.")
            return
        if method in {"Debit Card", "Credit Card"}:
            card_number = re.sub(r"[ -]", "", payment_details)
            if not card_number.isdigit() or not 12 <= len(card_number) <= 19 or not self._valid_card_number(card_number):
                messagebox.showerror("Error", "Please enter a valid card number (12-19 digits).")
                return
        elif method == "Net Banking" and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 ._-]{2,63}", payment_details):
            messagebox.showerror("Error", "Enter a valid bank name or banking reference.")
            return
        outbound_seats = self.selected_outbound_seats if self.selected_return_flight else self.selected_seats
        if len(outbound_seats) != self._required_seat_count():
            messagebox.showerror("Error", "Select the required number of outbound seats before confirming payment.")
            self._active_leg = "outbound"
            self.seat_page()
            return
        if self.selected_return_flight and len(self.selected_return_seats) != self._required_seat_count():
            messagebox.showerror("Error", "Select the required number of return seats before confirming payment.")
            self._active_leg = "return"
            self.seat_page()
            return

        self._booking_in_progress = True
        if button is not None:
            button.configure(state="disabled", text="PROCESSING...")
        now = datetime.now().strftime("%d-%m-%Y %I:%M %p")
        payment_reference = generate_booking_ref()
        outbound = self.selected_outbound_flight or {
            "flight_no": self.selected_flight,
            "airline": self.selected_airline,
            "route": self.selected_route,
            "date": self.selected_date,
            "price": self.selected_price
        }
        legs = [(outbound, outbound_seats)]
        if self.selected_return_flight:
            legs.append((self.selected_return_flight, self.selected_return_seats))
        booking_items = []

        try:
            for leg, seats in legs:
                booking_items.append((
                    self.current_user["email"], passenger_name, leg["flight_no"],
                    leg["airline"], leg["route"], leg["date"],
                    self.selected_travellers, self.selected_class, self.selected_fare,
                    ", ".join(seats), int(leg["price"]), method,
                    payment_reference, "Confirmed", now,
                    json.dumps({"passengers": self.selected_passenger_details, "mobile": mobile})
                ))
            booking_ids = self.db.create_bookings_with_payment(
                booking_items, method, payment_reference,
                expected_total=int(self.selected_price)
            )
        except Exception as error:
            self._booking_in_progress = False
            if button is not None:
                button.configure(state="normal", text="PAY & CONFIRM")
            messagebox.showerror("Booking Error", f"Booking could not be completed:\n{error}")
            return

        seats = outbound_seats
        booking_id = booking_ids[0]
        ticket_date = self.selected_date
        if self.selected_return_date:
            ticket_date = f"{self.selected_date} outbound  ⇄  {self.selected_return_date} return"
        ticket = {
            "booking_id": booking_id,
            "booking_ids": booking_ids,
            "passenger": passenger_name,
            "passengers": list(self.selected_passenger_names),
            "email": self.current_user["email"],
            "airline": outbound["airline"],
            "flight_no": outbound["flight_no"],
            "route": self.selected_route,
            "travel_date": ticket_date,
            "return_date": self.selected_return_date,
            "return_flight": self.selected_return_flight,
            "return_seat": ", ".join(self.selected_return_seats),
            "travellers": self.selected_travellers,
            "travel_class": self.selected_class,
            "fare_type": self.selected_fare,
            "seat": ", ".join(seats),
            "mobile": mobile,
            "price": self.selected_price,
            "payment_method": method,
            "payment_reference": payment_reference
        }
        try:
            pdf = create_ticket_pdf(ticket)
            ticket["pdf_path"] = pdf
            confirmation = (
                f"Payment successful!\nBooking confirmed.\n"
                f"Booking ID / PNR: {', '.join(str(item) for item in booking_ids)}\nSeats: {', '.join(seats)}"
                + (f"\nReturn flight: {self.selected_return_flight['flight_no']} | Seats: {', '.join(self.selected_return_seats)}" if self.selected_return_flight else "") + "\n"
                f"Amount paid: ₹{self.selected_price:,}\n"
                f"Payment reference: {payment_reference}\nE-ticket: {pdf}"
            )
        except Exception as error:
            ticket["pdf_path"] = ""
            confirmation = (
                f"Payment successful and booking confirmed.\n"
                f"Booking ID / PNR: {', '.join(str(item) for item in booking_ids)}\nAmount paid: ₹{self.selected_price:,}\n"
                f"Payment reference: {payment_reference}\n"
                f"The PDF ticket could not be generated: {error}"
            )
        messagebox.showinfo("Payment Successful", confirmation)
        self.ticket_view_page(ticket)

    @staticmethod
    def _valid_card_number(card_number):
        checksum = 0
        reverse_digits = card_number[::-1]
        for index, character in enumerate(reverse_digits):
            digit = int(character)
            if index % 2:
                digit *= 2
                if digit > 9:
                    digit -= 9
            checksum += digit
        return checksum % 10 == 0

    @staticmethod
    def _gate_and_boarding_time(flight_no):
        """Deterministic (not random-every-render) gate + boarding time
        derived from the flight number, so the boarding pass shows the
        same details every time it's viewed for the same booking."""
        seeded = random.Random(flight_no)
        gate = f"{seeded.choice('ABCDK')}{seeded.randint(1, 24)}"
        hour = seeded.randint(5, 22)
        minute = seeded.choice([0, 15, 30, 45])
        boarding_time = f"{hour:02d}:{minute:02d}"
        return gate, boarding_time

    def ticket_view_page(self, ticket):
        """A boarding-pass styled confirmation screen shown right after
        a successful booking, in addition to the PDF ticket. Uses a
        grid layout (instead of fixed x/y coordinates) so each field's
        row grows to fit its text — long names/routes wrap instead of
        getting clipped or overlapping the row below. The whole thing
        sits inside a scrollable frame so it's never cut off, even on
        a small screen."""
        self.clear(); self.background(); self.topbar("Your Boarding Pass")
        gate, boarding_time = self._gate_and_boarding_time(ticket["flight_no"])
        route_from, _, route_to = ticket["route"].partition("→")
        return_flight = ticket.get("return_flight")

        main_w, stub_w, gap_w = 640, 260, 20
        panel_h = 600 if return_flight else 480

        viewport_w = min(self.screen_w - 80, main_w + gap_w + stub_w + 60)
        viewport_h = min(self.screen_h - 140, panel_h + 130)
        scroll_wrap = ctk.CTkScrollableFrame(self, width=viewport_w, height=viewport_h,
                                              fg_color="transparent",
                                              scrollbar_button_color="#00CFEA")
        scroll_wrap.place(relx=0.5, rely=0.5, anchor="center")
        self._enable_mousewheel_scroll(scroll_wrap)

        outer = ctk.CTkFrame(scroll_wrap, width=main_w + gap_w + stub_w, height=panel_h, fg_color="transparent")
        outer.pack(pady=(6, 16))
        outer.pack_propagate(False)

        # --- main boarding-pass panel ---
        main = ctk.CTkFrame(outer, width=main_w, height=panel_h, fg_color="#081F33", corner_radius=28,
                     border_width=1, border_color="#147DFF")
        main.place(x=0, y=0)
        main.pack_propagate(False)

        header = ctk.CTkFrame(main, height=56, fg_color=BLUE_COLOR, corner_radius=0)
        header.pack(fill="x")
        ctk.CTkLabel(header, text="✈  SKYBOOK PRO", font=FONT_BODY_BOLD, text_color="white").pack(side="left", padx=20)
        ctk.CTkLabel(header, text="BOARDING PASS", font=FONT_SMALL_BOLD, text_color="#EDE9FE").pack(side="right", padx=20)

        body = ctk.CTkFrame(main, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=24, pady=(14, 0))
        body.grid_columnconfigure(0, weight=1, uniform="col")
        body.grid_columnconfigure(1, weight=1, uniform="col")

        def field_cell(parent, label_text, value_text, row, col,
                       value_font=FONT_BODY_BOLD, value_color=TEXT_PRIMARY):
            cell = ctk.CTkFrame(parent, fg_color="transparent")
            cell.grid(row=row, column=col, sticky="w", padx=(0, 16), pady=8)
            ctk.CTkLabel(cell, text=label_text, font=FONT_TINY, text_color=TEXT_MUTED).pack(anchor="w")
            ctk.CTkLabel(cell, text=value_text, font=value_font, text_color=value_color,
                         wraplength=260, justify="left").pack(anchor="w")

        field_cell(body, "PASSENGER", ticket["passenger"].upper(), 0, 0)
        field_cell(body, "CLASS", ticket["travel_class"], 0, 1)
        field_cell(body, "FLIGHT", f'{ticket["airline"]} · {ticket["flight_no"]}', 1, 0)
        field_cell(body, "DATE", ticket["travel_date"], 1, 1)
        field_cell(body, "FROM", route_from.strip(), 2, 0)
        field_cell(body, "TO", route_to.strip(), 2, 1)
        field_cell(body, "GATE", gate, 3, 0, value_font=FONT_H4, value_color=ACCENT_COLOR)
        field_cell(body, "BOARDING TIME", boarding_time, 3, 1, value_font=FONT_H4, value_color=ACCENT_COLOR)
