    def booking_history(self):
        self.clear(); self.background()
        self.topbar("My Bookings", back_command=self.home_page, back_text="← Back to Home")
        frame = ctk.CTkFrame(self, width=min(1120, self.screen_w - 40), height=620,
                     fg_color="#081F33", bg_color="transparent", corner_radius=28,
                     border_width=1, border_color="#147DFF")
        frame.pack(pady=(78, 20)); frame.pack_propagate(False)
        booking_list = ctk.CTkScrollableFrame(
            frame, width=1040, height=475, fg_color="transparent",
            scrollbar_button_color=PRIMARY_COLOR
        )
        booking_list.pack(fill="both", expand=True, padx=18, pady=(16, 8))
        self._enable_mousewheel_scroll(booking_list)
        rows = self.db.user_bookings(self.current_user["email"])
        if not rows:
            ctk.CTkLabel(
                booking_list, text="No bookings found.", font=FONT_H3,
                text_color=TEXT_MUTED
            ).pack(pady=40)
        for row in rows:
            booking_card = ctk.CTkFrame(
                booking_list, fg_color="#0D304A", corner_radius=10,
                border_width=1, border_color="#28617F"
            )
            booking_card.pack(fill="x", padx=6, pady=6)
            details = (
                f"Booking #{row[0]}   |   {row[1]} - {row[2]}\n"
                f"Route: {row[3]}   |   Date: {row[4]}\n"
                f"Travellers: {row[5]}   |   Class: {row[6]}   |   Fare: {row[7]}\n"
                f"Seat: {row[8]}   |   Price: ₹{row[9]}   |   Status: {row[10]}\n"
                f"Booked at: {row[11]}"
            )
            if str(row[10]).strip().lower() == "cancelled":
                cancellation_id = row[12] if len(row) > 12 and row[12] else f"CNL-{int(row[0]):06d}"
                cancellation_reason = row[13] if len(row) > 13 and row[13] else "Customer requested cancellation"
                details += f"\nCancellation ID: {cancellation_id}   |   Reason: {cancellation_reason}"
            ctk.CTkLabel(
                booking_card, text=details, font=FONT_SMALL,
                text_color=TEXT_PRIMARY, justify="left", anchor="w"
            ).pack(side="left", fill="x", expand=True, padx=12, pady=10)
            is_expired = False
            try:
                departure_text = str(row[4]).split("⇄")[0].strip()
                is_expired = datetime.strptime(departure_text, "%d-%m-%Y").date() < datetime.now().date()
            except (ValueError, TypeError):
                pass
            if is_expired and str(row[10]).strip().lower() != "cancelled":
                ctk.CTkLabel(
                    booking_card, text="Cancellation closed", font=FONT_SMALL_BOLD,
                    text_color=TEXT_MUTED
                ).pack(side="right", padx=12, pady=10)
            else:
                ctk.CTkButton(
                    booking_card, text="Cancel Request", width=135, height=34,
                    fg_color=ERROR_COLOR, hover_color=ERROR_HOVER,
                    font=FONT_SMALL_BOLD,
                    state="disabled" if str(row[10]).strip().lower() == "cancelled" else "normal",
                    command=lambda booking_id=row[0]: self.cancel_ticket(booking_id)
                ).pack(side="right", padx=12, pady=10)

    def cancel_ticket(self, booking_id):
        bid = str(booking_id).strip()
        # Do not allow cancellation after the booked travel date has expired.
        try:
            booking_rows = self.db.user_bookings(self.current_user["email"])
            booking = next((row for row in booking_rows if str(row[0]) == bid), None)
            if booking is None:
                messagebox.showerror("Error", "Booking not found")
                self.booking_history()
                return

            if str(booking[10]).strip().lower() == "cancelled":
                messagebox.showwarning("Cancellation", "This ticket is already cancelled.")
                self.booking_history()
                return

            travel_text = str(booking[4]).strip()
            # Round-trip bookings store the departure date first.
            departure_text = travel_text.split("⇄")[0].strip()
            travel_date = datetime.strptime(departure_text, "%d-%m-%Y").date()
            today = datetime.now().date()
            if travel_date < today:
                messagebox.showerror(
                    "Cancellation Expired",
                    f"This ticket cannot be cancelled because the travel date ({departure_text}) has already expired."
                )
                self.booking_history()
                return
        except (ValueError, TypeError):
            messagebox.showerror("Cancellation Error", "The booking has an invalid travel date.")
            self.booking_history()
            return
        except Exception as error:
            messagebox.showerror("Cancellation Error", str(error))
            self.booking_history()
            return

        reason = simpledialog.askstring(
            "Cancellation Reason",
            "Please enter the reason for cancelling this ticket:",
            parent=self
        )
        if reason is None:
            return
        reason = reason.strip()
        if not reason:
            messagebox.showwarning("Cancellation", "Please enter a cancellation reason.")
            return

        result = self.db.cancel_booking(bid, self.current_user["email"], reason)
        count, cancellation_id = result if isinstance(result, tuple) else (result, f"CNL-{int(bid):06d}")
        if count:
            messagebox.showinfo("Success", f"Ticket cancelled successfully\nCancellation ID: {cancellation_id}\nReason sent: {reason}\nRefund amount: ticket price")
        else:
            messagebox.showerror("Error", "Booking not found or already cancelled")
        self.booking_history()

