    def admin_refunds(self):
        # Show every cancelled booking together with its refund amount/status.
        # A pending refund is created automatically when a cancelled booking
        # does not already have a refund record, so there is no separate
        # "Create Request" step in the admin UI.
        cancelled_rows = [r for r in self.db.all_bookings() if str(r[9]).strip().lower() == "cancelled"]
        refund_rows = self.db.all_refunds()
        refund_by_booking = {}
        for rr in refund_rows:
            refund_by_booking[int(rr[1])] = rr

        # Keep cancelled bookings and refunds in sync automatically.
        for r in cancelled_rows:
            booking_id = int(r[0])
            if booking_id not in refund_by_booking:
                try:
                    amount = int(r[8] or 0)
                    if amount > 0 and self.db.create_refund_request(booking_id, amount):
                        pass
                except Exception:
                    pass
        refund_rows = self.db.all_refunds()
        refund_by_booking = {int(rr[1]): rr for rr in refund_rows}

        def fmt_cancel(r):
            cid = r[11] if len(r) > 11 and r[11] else f"CNL-{int(r[0]):06d}"
            refund = refund_by_booking.get(int(r[0]))
            refund_amount = int(refund[2]) if refund and refund[2] is not None else int(r[8] or 0)
            refund_status = refund[3] if refund else "Pending"
            reason = r[12] if len(r) > 12 and r[12] else "Customer requested cancellation"
            return (cid, r[0], r[1], r[3], r[6], f"₹{refund_amount:,}", refund_status, r[9], reason)

        frame = self._admin_data_table(
            "Cancellation & Refund Center", "Cancelled tickets, cancellation IDs and refund amount/status",
            ("CANCELLATION ID", "BOOKING ID", "PASSENGER", "FLIGHT", "TRAVEL DATE", "REFUND AMOUNT", "REFUND STATUS", "STATUS", "REASON"),
            cancelled_rows, fmt_cancel, "Search cancellation / booking / passenger...",
            search_indexes=(0, 1, 2, 3, 6, 7, 8)
        )

        controls=ctk.CTkFrame(frame,fg_color=PANEL,corner_radius=16,border_width=1,border_color="#1E5A8F")
        controls.pack(fill="x",padx=30,pady=(0,12))
        bid=ctk.CTkEntry(controls,placeholder_text="Booking ID",width=150,height=40)
        bid.pack(side="left",padx=10,pady=10)
        amount=ctk.CTkEntry(controls,placeholder_text="Refund amount",width=170,height=40)
        amount.pack(side="left",padx=10,pady=10)

        def process_refund():
            try:
                if not bid.get().strip():
                    raise ValueError("Enter Booking ID.")
                if not amount.get().strip():
                    raise ValueError("Enter Refund amount.")

                booking_id = int(bid.get().strip())
                refund_amount = int(amount.get().strip())
                if booking_id <= 0 or refund_amount <= 0:
                    raise ValueError("Booking ID and Refund amount must be positive.")

                refund_rows_now = self.db.all_refunds()
                pending = None
                for rr in refund_rows_now:
                    if int(rr[1]) == booking_id and str(rr[3]).strip().lower() == "pending":
                        pending = rr
                        break

                if not pending:
                    messagebox.showerror("Refund", "No pending refund found for this Booking ID.")
                    return

                if int(pending[2]) != refund_amount:
                    messagebox.showerror(
                        "Refund",
                        f"Refund amount mismatch. Pending amount is ₹{int(pending[2]):,}."
                    )
                    return

                if self.db.update_refund_status(int(pending[0]), "Processed"):
                    messagebox.showinfo("Refund", "Refund marked as processed.")
                    self.admin_refunds()
                else:
                    messagebox.showerror("Refund", "Could not process the refund.")
            except ValueError as e:
                messagebox.showerror("Refund Error", str(e))
            except Exception as e:
                messagebox.showerror("Refund Error", str(e))

        ctk.CTkButton(
            controls,text="Process Refund",height=40,corner_radius=18,
            fg_color="#0C9B7A",hover_color="#047857",command=process_refund
        ).pack(side="left",padx=8)

        refund_rows=self.db.all_refunds()
        refund_card=ctk.CTkFrame(frame,fg_color=PANEL,corner_radius=16,border_width=1,border_color="#1E5A8F")
        refund_card.pack(fill="both",expand=True,padx=30,pady=(0,22))
        refund_table=ctk.CTkScrollableFrame(refund_card,fg_color="#0B2C45",corner_radius=14,border_width=1,border_color="#1E5A8F")
        refund_table.pack(fill="both",expand=True,padx=12,pady=12)
        self._enable_mousewheel_scroll(refund_table)
        cols=("REFUND ID","BOOKING ID","AMOUNT","STATUS","PROCESSED","PASSENGER","FLIGHT","CANCEL ID","REASON")
        hdr=ctk.CTkFrame(refund_table,fg_color="#103B5C",corner_radius=8,height=34); hdr.pack(fill="x",padx=6,pady=(6,4)); hdr.pack_propagate(False)
        for i,c in enumerate(cols):
            hdr.grid_columnconfigure(i,weight=1,uniform="refundcols")
            ctk.CTkLabel(hdr,text=c,font=FONT_TINY_BOLD,text_color="#43DFFF",anchor="w").grid(row=0,column=i,sticky="ew",padx=7)
        # Database refund records currently contain 7 fields:
        # id, booking_id, amount, status, processed_at, passenger, flight_no.
        # Build the remaining display columns safely instead of indexing beyond
