    def _parse_travel_date(self, value):
        """Return the departure date from the app's dd-mm-yyyy travel-date text."""
        text = str(value or "").strip().split("⇄", 1)[0].strip()
        for fmt in ("%d-%m-%Y", "%d/%m/%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, fmt).date()
            except ValueError:
                continue
        return None

    def track_flight(self):
        flight_no = self.track_flight_entry.get().strip().upper()
        if not flight_no:
            messagebox.showerror("Error", "Please enter one of your current booking flight numbers")
            return

        today = datetime.now().date()
        current_booking = None
        current_bookings = []
        try:
            for row in self.db.user_bookings(self.current_user["email"]):
                if len(row) <= 10 or str(row[10]).strip().lower() != "confirmed":
                    continue
                if str(row[1]).strip().upper() != flight_no:
                    continue
                travel_date = self._parse_travel_date(row[4]) if len(row) > 4 else None
                if travel_date is not None and travel_date >= today:
                    current_bookings.append((travel_date, row))
            if current_bookings:
                current_booking = min(current_bookings, key=lambda item: item[0])[1]
        except Exception as error:
            messagebox.showerror("Tracker Error", f"Unable to read booking data: {error}")
            return

        # Tracker is intentionally limited to the logged-in user's current/future
        # booked flight numbers. Expired/cancelled tickets are automatically hidden.
        if current_booking is None:
            self.track_result.configure(state="normal")
            self.track_result.delete("1.0", "end")
            self.track_result.insert(
                "end",
                f"Flight {flight_no} is not in your current bookings.\n\n"
                "Expired and cancelled flight numbers are automatically removed from the tracker.\n"
                "Use one of the current booking flight numbers shown above."
            )
            self.track_result.configure(state="disabled")
            return

        try:
            flights = self.db.all_flights() or []
            flight = next((row for row in flights
                           if len(row) > 1 and str(row[1]).strip().upper() == flight_no), None)
        except Exception as error:
            messagebox.showerror("Tracker Error", f"Unable to read flight data: {error}")
            return

        if not flight:
            self.track_result.configure(state="normal")
            self.track_result.delete("1.0", "end")
            self.track_result.insert("end", f"Flight {flight_no} is no longer available in the SkyBook flight database.")
            self.track_result.configure(state="disabled")
            return

        _, number, airline, source, destination, depart, arrive, duration, seats, fare, db_status = flight
        booking_date = self._parse_travel_date(current_booking[4])
        booked_seats = 0
        try:
            booked_seats = len(self.db.booked_seats(number, booking_date.strftime("%d-%m-%Y")))
        except Exception:
            booked_seats = 0
        available = max(0, int(seats) - booked_seats)
        display_status = str(db_status or "Scheduled")

        self.track_result.configure(state="normal")
        self.track_result.delete("1.0", "end")
        details = (
            f"Flight Number : {number}\n"
            f"Airline       : {airline}\n"
            f"Route         : {source} → {destination}\n"
            f"Departure     : {depart}\n"
            f"Arrival       : {arrive}\n"
            f"Duration      : {duration}\n"
            f"Status        : {display_status}\n"
            f"Available Seats: {available}\n"
            f"Current Fare  : ₹{int(fare):,}\n"
            f"Booking ID    : {current_booking[0]}\n"
            f"Booking Status: {current_booking[10]}\n"
        )
        self.track_result.insert("end", details)
        self.track_result.configure(state="disabled")

