    def swap_compare_airports(self):
        source = self.compare_from.get().strip()
        destination = self.compare_to.get().strip()
        if not source or not destination:
            messagebox.showerror("Swap Error", "Please select both airports first.")
            return
        self.compare_from.set(destination)
        self.compare_to.set(source)

    def compare_flights(self):
        source = self._resolve_airport(self.compare_from.get()) or self.compare_from.get().strip()
        destination = self._resolve_airport(self.compare_to.get()) or self.compare_to.get().strip()
        if source == destination:
            messagebox.showerror("Error", "From and To airport cannot be the same")
            return

        try:
            flights = self.db.search_flights(source, destination)
        except Exception as error:
            messagebox.showerror("Comparison Error", f"Unable to read flight data: {error}")
            return

        if not flights:
            self.compare_result.delete("1.0", "end")
            self.compare_result.insert("end", "No flights found for this route in the SkyBook database.")
            return

        def duration_minutes(value):
            match = re.match(r"(\d+)h\s*(\d+)m", str(value))
            if match:
                return int(match.group(1)) * 60 + int(match.group(2))
            return 99999

        cheapest = min(flights, key=lambda x: int(x[8]))
        fastest = min(flights, key=lambda x: duration_minutes(x[6]))
        balanced = min(flights, key=lambda x: int(x[8]) + duration_minutes(x[6]) * 20)

        self.compare_result.delete("1.0", "end")
        for label, flight in [("LOWEST FARE", cheapest), ("FASTEST", fastest), ("BEST BALANCED", balanced)]:
            self.compare_result.insert(
                "end",
                f"{label}\n"
                f"{flight[0]} | {flight[1]} | {flight[2]} → {flight[3]} | "
                f"{flight[4]} - {flight[5]} | {flight[6]} | ₹{int(flight[8]):,} | {flight[9]}\n"
                + "-" * 80 + "\n"
            )

