    def show_weather_alert(self):
        city = self.weather_city.get().strip()
        if not city:
            messagebox.showerror("Error", "Select a destination first")
            return

        # Use a public weather endpoint. No random/simulated weather values.
        query = city.split("(")[0].strip()
        try:
            request = Request(
                "https://wttr.in/" + quote(query) + "?format=j1",
                headers={"User-Agent": "SkyBook-Pro/1.0"}
            )
            with urlopen(request, timeout=6) as response:
                payload = json.loads(response.read().decode("utf-8"))
            current = payload["current_condition"][0]
            temperature = current.get("temp_C", "-")
            condition = current.get("weatherDesc", [{"value": "Unknown"}])[0].get("value", "Unknown")
            wind = current.get("windspeedKmph", "-")
            humidity = current.get("humidity", "-")
            visibility = current.get("visibility", "-")
            alert = "Check airline/airport notices before departure."
            self.weather_result.configure(state="normal")
            self.weather_result.delete("1.0", "end")
            self.weather_result.insert(
                "end",
                f"Destination  : {city}\n"
                f"Temperature  : {temperature}°C\n"
                f"Condition    : {condition}\n"
                f"Wind         : {wind} km/h\n"
                f"Humidity     : {humidity}%\n"
                f"Visibility   : {visibility} km\n\n"
                f"Travel Alert : {alert}\n\n"
                "Weather data fetched from the public wttr.in service."
            )
            self.weather_result.configure(state="disabled")
        except Exception as error:
            self.weather_result.configure(state="normal")
            self.weather_result.delete("1.0", "end")
            self.weather_result.insert("end", "Live weather could not be loaded right now.\n\n"
                                       f"Reason: {error}\n\n"
                                       "No fake/random weather values are shown.")
            self.weather_result.configure(state="disabled")

