    def ai_reply(self):
        question = self.chat_entry.get().strip()
        if not question:
            return
        q = re.sub(r"[^a-z0-9#\- ]+", " ", question.lower())
        q = re.sub(r"\s+", " ", q).strip()
        tokens = set(q.split())

        def current_bookings():
            today = datetime.now().date()
            result = []
            try:
                for r in self.db.user_bookings(self.current_user["email"]):
                    if len(r) <= 10 or str(r[10]).strip().lower() != "confirmed":
                        continue
                    d = self._parse_travel_date(r[4]) if len(r) > 4 else None
                    if d is not None and d >= today:
                        result.append(r)
            except Exception:
                pass
            return result

        def show_user_flights():
            bookings = current_bookings()
            if not bookings:
                return "You have no current active flight bookings. Expired and cancelled tickets are removed from Flight Tracker."
            lines = []
            for r in bookings[:8]:
                lines.append(f"{r[1]} | {r[3]} | {r[4]} | Confirmed")
            return "Your current flight details:\n" + "\n".join(lines)

        if "admin" in tokens and "login" in tokens:
            answer = "Admin Login is available from the Login page → Admin Login. It requires an authorized admin email and password. SkyBot does not display or reveal admin credentials."
        elif any(word in q for word in ("cancellation", "cancel ticket", "cancel booking", "cancel my", "how i cancellation", "how to cancel", "cancellation option")) or "cancel" in tokens:
            answer = "To cancel a ticket, open My Bookings and select a current/future confirmed ticket. Expired tickets cannot be cancelled. After cancellation, check Refund Status for the refund progress."
        elif "refund" in tokens:
            answer = "Open Refund Status to view your own cancelled bookings and refund progress."
        elif "flight tracker" in q or "track flight" in q or "tracker" in tokens or "track" in tokens:
            bookings = current_bookings()
            if bookings:
                nums = []
                for r in bookings:
                    if r[1] not in nums:
                        nums.append(str(r[1]))
                answer = "Your current Flight Tracker numbers: " + ", ".join(nums) + ". Expired and cancelled flight numbers are automatically removed."
            else:
                answer = "You have no current flight to track. Expired and cancelled flight numbers are automatically removed."
        elif ("my" in tokens and ("flight" in tokens or "booking" in tokens)) or "flight number" in q or "my flight details" in q or "booking details" in q or "details" in q:
            answer = show_user_flights()
        elif "expired" in tokens or "expire" in tokens or "past flight" in q:
            answer = "Expired flights are automatically removed from Flight Tracker. Only current/future confirmed bookings are shown there."
        elif "baggage" in tokens or "luggage" in tokens:
            answer = "Baggage up to 19 kg is allowed normally; 20-25 kg is allowed with an extra baggage charge; above 25 kg is not allowed."
        elif "payment" in tokens or "pay" in tokens:
            answer = "SkyBook supports UPI, Debit Card, Credit Card, and Net Banking on the Payment screen. Actual UPI/card numbers are not displayed in Booking Management."
        elif "price" in tokens or "cheap" in tokens or "fare" in tokens:
            answer = "Use Compare Flights to find the cheapest, fastest, or best-balanced option, or Fare Calendar for low-fare dates."
        elif "seat" in tokens or "seats" in tokens:
            answer = "Green seats are available and red seats are already booked; tap a seat to select it."
        elif "book" in tokens or "booking" in tokens:
            answer = "Search a route, choose a flight, select your seat(s), and complete the demo payment to book."
        elif "skybook" in tokens or "skybot" in tokens or "hello" in tokens or "hi" in tokens:
            answer = "Hi! I'm SkyBot. Ask me about your current flight, booking details, flight tracker, baggage, price, seats, cancellation or refund."
        else:
            answer = "I can help with current flight details, Flight Tracker, baggage, price, seats, cancellation, refund and admin login. Try: 'show my flight details' or 'how to cancel'."

        self.chat_output.insert("end", f"You: {question}\nSkyBot: {answer}\n\n")
        self.chat_output.see("end")
        self.chat_entry.delete(0, "end")

    def _sync_multicity_leg(self, index):
        """Round-trip chaining rule: when leg [index]'s destination
        changes, the NEXT leg's origin must automatically match it.
        Only the next leg's FROM is touched — its own destination is
        left exactly as the user set it. The next leg's FROM box is
        disabled (user can't edit it directly), so it's briefly
        re-enabled here to apply the programmatic update, then
        disabled again."""
        if not hasattr(self, "multi_rows") or index + 1 >= len(self.multi_rows):
            return
        new_destination = self.multi_rows[index][1].get()
        next_from_box = self.multi_rows[index + 1][0]
        next_from_box.configure(state="normal")
        next_from_box.set(new_destination)
        next_from_box.configure(state="disabled")

