    def create_multi_city_plan(self):
        lines = []
        total = 0
        for i, (from_box, to_box, date_box) in enumerate(self.multi_rows, start=1):
            source = self._resolve_airport(from_box.get()) or from_box.get().strip()
            destination = self._resolve_airport(to_box.get()) or to_box.get().strip()
            if source == destination:
                messagebox.showerror("Error", f"Leg {i}: From and To cannot be same")
                return
            try:
                flights = self.db.search_flights(source, destination)
            except Exception as error:
                messagebox.showerror("Trip Plan Error", f"Unable to read leg {i}: {error}")
                return
            if not flights:
                messagebox.showerror("Trip Plan Error", f"No flight found for Leg {i}: {source} → {destination}")
                return
            best = min(flights, key=lambda row: int(row[8]))
            fare = int(best[8])
            total += fare
            lines.append(
                f"Leg {i}: {source} → {destination} | {date_box.get()} | "
                f"{best[0]} ({best[1]}) | ₹{fare:,}"
            )
        self.multi_result.delete("1.0", "end")
        self.multi_result.insert("end", "\n".join(lines) + f"\n\nCurrent lowest total: ₹{total:,}")

