    def _calendar_lowest_base_fare(self, source, destination):
        try:
            flights = self.db.search_flights(source, destination)
            valid = [int(row[8]) for row in flights if len(row) > 8 and str(row[8]).isdigit()]
            if valid:
                return min(valid)
        except Exception as error:
            print(f"Fare calendar database lookup failed: {error}")
        return None

    def _use_fare_calendar_date(self, source, destination, day, fare):
        self.fare_calendar_route = f"{source} → {destination}"
        self.fare_calendar_date = day.strftime("%d-%m-%Y")
        self.fare_calendar_price = int(fare)
        self.fare_calendar_flight_no = ""

        # Keep booking defaults aligned with the fare-calendar price.
        self.selected_date = self.fare_calendar_date
        self.selected_return_date = ""
        self.selected_route = self.fare_calendar_route
        self.selected_travellers = "1 Member"
        self.selected_class = "Economy"
        self.selected_fare = "Regular"

        try:
            flights = self.db.search_flights(source, destination)
        except Exception as error:
            flights = []
            print(f"Fare-calendar booking lookup failed: {error}")

        if not flights:
            flights = self.temp_flights(source, destination)

        if flights:
            # Always put the cheapest real route flight first so the calendar
            # price is guaranteed to be visible in the first 5 booking cards.
            try:
                flights = sorted(flights, key=lambda row: int(row[8]))
            except Exception:
                pass
            self.fare_calendar_flight_no = str(flights[0][0]).strip()
            self.results_page(flights)
        else:
            messagebox.showerror("Booking Error", "No flights are available for this route.")

    def generate_fare_calendar(self):
        source = self._resolve_airport(self.fare_from.get()) or self.fare_from.get().strip()
        destination = self._resolve_airport(self.fare_to.get()) or self.fare_to.get().strip()
        if not source or not destination:
            return
        if source == destination:
            messagebox.showerror("Error", "From and To cannot be same")
            return

        base_fare = self._calendar_lowest_base_fare(source, destination)
        if base_fare is None:
            # Fallback only when the selected route is not present in the demo DB.
            base_fare = 6500

        # Deterministic daily pricing based on the route's real lowest flight fare.
        # The selected calendar fare is carried into the booking flow exactly.
        adjustments = [1.08, 1.00, 1.12, 1.05, 1.18, 1.03, 1.10]
        days = []
        for i, multiplier in enumerate(adjustments, start=1):
            day = datetime.now() + timedelta(days=i)
            fare = int(round((base_fare * multiplier) / 250) * 250)
            if i == 2:
                fare = base_fare
            days.append((day, fare))

        cheapest = min(days, key=lambda item: item[1])
        for widget in self.fare_result.winfo_children():
            widget.destroy()

        header = ctk.CTkFrame(self.fare_result, fg_color="#081F33", corner_radius=14)
        header.pack(fill="x", padx=8, pady=(8, 10))
        ctk.CTkLabel(header, text=f"{source}  →  {destination}", font=FONT_H4,
                     text_color=TEXT_PRIMARY).pack(side="left", padx=16, pady=10)
        ctk.CTkLabel(header, text=f"Lowest available: ₹{cheapest[1]:,}", font=FONT_BODY_BOLD,
                     text_color=SUCCESS_COLOR).pack(side="right", padx=16, pady=10)

        for day, fare in days:
            row = ctk.CTkFrame(self.fare_result, fg_color="#142A4A", corner_radius=14, height=58)
            row.pack(fill="x", padx=8, pady=5)
            row.pack_propagate(False)
            is_lowest = day == cheapest[0]
            label = day.strftime("%a, %d %b %Y")
            ctk.CTkLabel(row, text=label, width=190, anchor="w",
                         font=FONT_BODY_BOLD, text_color=TEXT_PRIMARY).pack(side="left", padx=14)
            ctk.CTkLabel(row, text=f"₹{fare:,}" + ("  ★ LOWEST" if is_lowest else ""),
                         width=180, anchor="w", font=FONT_BODY_BOLD,
                         text_color=SUCCESS_COLOR if is_lowest else ACCENT_COLOR).pack(side="left")
            ctk.CTkButton(row, text="BOOK THIS FARE", width=145, height=34, corner_radius=17,
                          fg_color=PRIMARY_COLOR if is_lowest else "#103B5C",
                          hover_color=PRIMARY_HOVER, font=FONT_SMALL_BOLD,
                          command=lambda d=day, f=fare: self._use_fare_calendar_date(source, destination, d, f)).pack(side="right", padx=12)

